service-call.in-map:
{workEffortName:(workEffortName || ''),
                    rootWorkEffortId:(ec.context.get('projectTabId') || rootWorkEffortId || projectId || null), purposeEnumId:(purposeEnumId || null), assignToPartyId:(assignToPartyId || null),
                    sprintWorkEffortId:(addSprintId || null)}

actions.script:
let kept = {}
try { kept = JSON.parse(keep || '{}') || {} } catch (err) { kept = {} }
ec.context.putAll(kept)

let kept = {}
try { kept = JSON.parse(keep || '{}') || {} } catch (err) { kept = {} }
ec.context.putAll(kept)

const out = ec.service.sync().name('ironstone.projects.WorkItemServices.update#WorkItemField').parameters({workEffortId: workEffortId, field: field,
    value: value == null ? '' : value}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {valueText: out.valueText, messageInfos: [{type: 'success', message: out.message}]})

const access = ec.service.sync().name('ironstone.commons.TaskServices.get#TaskAccess').parameters({workEffortId: workEffortId, need: 'view', app: 'projects'}).call()
let value = ''
if (!ec.message.hasError() && access.workEffort) {
    const item = access.workEffort
    if (field === 'due') value = item.estimatedCompletionDate != null && item.estimatedCompletionDate !== '' ? ec.l10n.format(item.estimatedCompletionDate, 'yyyy-MM-dd') : ''
    else if (field === 'priority') value = item.priority != null ? String(item.priority) : ''
}
ec.web.sendJsonResponse({value: value})

const day = estimatedCompletionDate == null ? '' : String(estimatedCompletionDate).trim().substring(0, 10)
if (!day) { ec.message.addError(ec.l10n.localize('Drop the work item on a day')); ec.web.sendJsonResponse({}); return }
const out = ec.service.sync().name('ironstone.projects.WorkItemServices.update#WorkItemField').parameters({workEffortId: workEffortId, field: 'due', value: day}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {messageInfos: [{type: 'success', message: out.message}]})

const wanted = String(ids || '').split(',').map((id) => id.trim()).filter((id) => id)
const found = wanted.length ? ec.service.sync().name('mantle.work.ProjectServices.get#WorkItemTree').parameters({workEffortIds: wanted, withAncestors: true}).call() : {}
const rows = Array.from(found?.workItemList || [])
const decorated = rows.length ? ec.service.sync().name('ironstone.projects.WorkItemServices.decorate#WorkItemRows').parameters({taskList: rows}).call()?.rowList || [] : []
ec.web.sendJsonResponse({workItemRows: decorated})

// in ProjectDetail's Work items tab (its always-actions put the project it shows in projectTabId) the project is fixed
projectFixed = !!ec.context.get('projectTabId')
if (projectFixed) rootWorkEffortId = ec.context.get('projectTabId')
const L = (text) => ec.l10n.localize(text)
const lists = [['open', 'Open', 'sym_o_checklist'], ['mine', 'Assigned to me', 'sym_o_person'], ['reported', 'Reported by me', 'sym_o_edit_note'],
    ['watching', 'Watching', 'sym_o_visibility'], ['unassigned', 'Unassigned', 'sym_o_person_off'], ['week', 'Due this week', 'sym_o_date_range'],
    ['overdue', 'Overdue', 'sym_o_assignment_late'], ['recent', 'Recently changed', 'sym_o_history'], ['done', 'Done', 'sym_o_task_alt'],
    ['all', 'All', 'sym_o_select_all']]
if (!lists.some((entry) => entry[0] === list)) list = 'open'
const param = (name) => { const value = ec.web.parameters[name]; return value == null || value === '' ? null : String(value) }
const ctx = (name) => { const value = ec.context.get(name); return value == null || value === '' ? null : String(value) }
// the due period of the find (a date-period field), or its from and thru
let dueFrom = null
let dueThru = null
if (ctx('due_period')) {
    const range = ec.user.getPeriodRange(ctx('due_period'), ctx('due_poffset') || '0', ctx('due_pdate'))
    if (range) { dueFrom = range[0]; dueThru = range[1] }
} else {
    if (ctx('due_from')) dueFrom = ec.l10n.parseTimestamp(ctx('due_from').substring(0, 10) + ' 00:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS')
    if (ctx('due_thru')) dueThru = new Date(Number(String(ec.l10n.parseTimestamp(ctx('due_thru').substring(0, 10) + ' 00:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS'))) + 86400000)
}
// the dates of the calendar (view-calendar range-find, epoch millis, thru inclusive)
const millisOf = (text) => text == null ? null : (/^-?\d+$/.test(text) ? Number(text) : (Number.isNaN(Date.parse(text)) ? null : Date.parse(text)))
const rangeFrom = millisOf(param('estimatedCompletionDate_from'))
const rangeThru = millisOf(param('estimatedCompletionDate_thru'))
if (rangeFrom != null && (dueFrom == null || rangeFrom > Number(String(dueFrom)))) dueFrom = new Date(rangeFrom)
if (rangeThru != null && (dueThru == null || rangeThru + 1 < Number(String(dueThru)))) dueThru = new Date(rangeThru + 1)
// a level of the tree (view-tree children, impl-projects.md F13), and every row of the board or calendar, without the counts
const treeParent = param('parentWorkEffortId')
const noLimit = param('pageNoLimit') === 'true'
const out = ec.service.sync().name('ironstone.projects.WorkItemServices.find#WorkItems').parameters({list: list, text: text || null,
    rootWorkEffortId: rootWorkEffortId || null, purposeEnumId: purposeEnumId || null, statusId: statusId || null, priorityBand: priorityBand || null,
    assigneePartyId: assigneePartyId || null, milestoneId: milestoneId || null, releaseId: releaseId || null, sprintId: sprintId || null, labelId: labelId || null,
    parentWorkEffortId: treeParent, underWorkEffortId: underWorkEffortId || null, topLevel: topLevel || null, visibilityEnumId: visibilityEnumId || null,
    recurring: recurring || null, dueFrom: dueFrom, dueThru: dueThru, treeOrder: param('view') === 'tree', orderByField: orderByField || null,
    pageIndex: Number(pageIndex || 0) || 0, pageSize: 25, pageNoLimit: noLimit || !!treeParent, withCounts: !noLimit && !treeParent}).call() || {}
workItemRows = Array.from(out.rowList || [])
workItemRowsCount = out.rowCount || 0
workItemRowsPageIndex = out.pageIndex || 0
workItemRowsPageSize = out.pageSize || 25
workItemRowsPageMaxIndex = out.pageMaxIndex || 0
workItemRowsPageRangeLow = out.pageRangeLow || 0
workItemRowsPageRangeHigh = out.pageRangeHigh || 0
const counts = out.counts || {}
keyMatch = out.keyMatch || null
hoursTotals = out.totals || {}

// the find as it is, kept by every change of the list
const find = {text: text || null, rootWorkEffortId: rootWorkEffortId || null, purposeEnumId: purposeEnumId || null, statusId: statusId || null,
    priorityBand: priorityBand || null, assigneePartyId: assigneePartyId || null, milestoneId: milestoneId || null, releaseId: releaseId || null,
    sprintId: sprintId || null, labelId: labelId || null, underWorkEffortId: underWorkEffortId || null, topLevel: topLevel || null, visibilityEnumId: visibilityEnumId || null,
    recurring: recurring || null, orderByField: orderByField || null, due_period: ctx('due_period'), due_poffset: ctx('due_poffset'),
    due_pdate: ctx('due_pdate'), due_from: ctx('due_from'), due_thru: ctx('due_thru')}
Object.keys(find).forEach((key) => { if (find[key] == null) delete find[key] })
filtered = Object.keys(find).some((key) => key !== 'orderByField')
// A screen URL inherits its declared parameters; empty values explicitly remove this find from the reset link.
clearFindParams = Object.assign(Object.fromEntries(Object.keys(find).map((key) => [key, ''])),
    {list: list, pageIndex: '', formListFindId: ''}, projectFixed ? {rootWorkEffortId: rootWorkEffortId} : {})
const keepMap = Object.assign({list: list}, find, workItemRowsPageIndex ? {pageIndex: String(workItemRowsPageIndex)} : {})
keepJson = JSON.stringify(keepMap)
listChips = lists.map(([key, label, icon]) => ({key: key, label: L(label) + ' · ' + (counts[key] || 0), icon: icon, on: key === list,
    params: Object.assign({}, find, {list: key})}))
listLabel = L(lists.find((entry) => entry[0] === list)[1])
// the drop-downs
projectOptions = ec.service.sync().name('ironstone.projects.WorkItemServices.get#ProjectOptions').call()?.projectList || []
addProjectOptions = ec.service.sync().name('ironstone.projects.WorkItemServices.get#ProjectOptions').parameters({memberOnly: true}).call()?.projectList || []
addProjectId = rootWorkEffortId ? (addProjectOptions.some((option) => option.key === rootWorkEffortId) ? rootWorkEffortId : '') : (addProjectOptions[0]?.key || '')
// the quick-add types: those the project offers (Settings, Work item types; the project's own WstWorkItemTypes)
addTypeOptions = Array.from(ec.service.sync().name('ironstone.projects.ProjectServices.get#WorkItemTypes').parameters({rootWorkEffortId: addProjectId || null}).call()?.offeredList || [])
addTypeId = addTypeOptions.some((type) => type.enumId === 'WepTask') ? 'WepTask' : (addTypeOptions[0]?.enumId || 'WepTask')
milestoneOptions = ec.service.sync().name('ironstone.projects.WorkItemServices.get#PlanItemOptions').parameters({rootWorkEffortId: rootWorkEffortId || null,
    workEffortTypeEnumId: 'WetMilestone'}).call()?.optionList || []
releaseOptions = ec.service.sync().name('ironstone.projects.WorkItemServices.get#PlanItemOptions').parameters({rootWorkEffortId: rootWorkEffortId || null,
    workEffortTypeEnumId: 'WetRelease'}).call()?.optionList || []
// the sprints: of the find (the sprints in progress, and those of the project), of the bulk change, of the quick add (its project)
sprintOptions = [{key: 'current', text: L('Current sprint (in progress)')}].concat(ec.service.sync().name('ironstone.projects.WorkItemServices.get#PlanItemOptions')
        .parameters({rootWorkEffortId: rootWorkEffortId || null, workEffortTypeEnumId: 'WetSprint'}).call()?.optionList || [])
bulkSprintOptions = sprintOptions.filter((option) => option.key !== 'current')
addSprintOptions = addProjectId ? Array.from(ec.service.sync().name('ironstone.projects.PlanningServices.get#SprintOptions').parameters({rootWorkEffortId: addProjectId}).call()?.optionList || []) : []
addSprintId = ''
if (sprintId && addSprintOptions.some((option) => option.key === sprintId)) addSprintId = sprintId
else if (sprintId === 'current') addSprintId = Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', addProjectId || '_NA_')
        .condition('workEffortTypeEnumId', 'WetSprint').condition('statusId', 'WeInProgress').orderBy('estimatedStartDate').list())[0]?.workEffortId || ''
labelOptions = ec.service.sync().name('ironstone.projects.WorkItemServices.get#LabelOptions').call()?.optionList || []
isProjectsManager = ec.user.isInGroup('BOSS_PROJECT_MANAGER') || ec.user.isInGroup('ADMIN')
const empty = {open: 'No open work items', mine: 'No open work items assigned to you', reported: 'No open work items you reported',
    watching: 'You are not watching any open work item', unassigned: 'Every open work item has an assignee', week: 'Nothing due this week',
    overdue: 'Nothing overdue', recent: 'Nothing changed in the last seven days', done: 'Nothing done yet', all: 'No work items'}
emptyText = filtered ? L('No work items match') : (addProjectOptions.length ? L(empty[list]) : L('No work items yet: you are on no project'))
newItemHtml = '<q-btn unelevated no-caps dense color="primary" class="q-ml-sm" icon="sym_o_add_task" label="' + sri.encodeHtml(L('New work item')) + '"'
        + ' @click="$root.openQuickCreate({url: \'/qapps/Projects/QuickCreate?kind=workItem' + (rootWorkEffortId ? '&rootWorkEffortId=' + encodeURIComponent(rootWorkEffortId) : '')
        + '\', label: \'' + sri.encodeHtml(L('New work item').replace(/['\\]/g, '')) + '\'})"></q-btn>'
